def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def parts(n, seps):
        out, start = [], 0
        for p in seps:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < n:
            out.append((start, n))
        return out

    rp, cp = parts(h, sep_rows), parts(w, sep_cols)
    regions = [(a, b, c, d) for a, b in rp for c, d in cp]
    source = max(regions, key=lambda z: sum(
        grid[r][c] != bg
        for r in range(z[0], z[1]) for c in range(z[2], z[3])
    ))
    a, b, c, d = source
    pattern = [row[c:d] for row in grid[a:b]]
    out = [row[:] for row in grid]

    for r0, r1, c0, c1 in regions:
        for dr in range(min(b - a, r1 - r0)):
            for dc in range(min(d - c, c1 - c0)):
                out[r0 + dr][c0 + dc] = pattern[dr][dc]
    return out
